import 'dart:convert';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_database/firebase_database.dart';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:image_picker/image_picker.dart';
import 'dart:typed_data';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  try { await Firebase.initializeApp(); } catch(e) {}
  runApp(const OnyxApp());
}
class OnyxApp extends StatelessWidget{ const OnyxApp({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false, theme:ThemeData.dark().copyWith(scaffoldBackgroundColor:Color(0xFF0A0A0A)), home:const Splash()); }
class Splash extends StatefulWidget{ const Splash({super.key}); @override State<Splash> createState()=>SplashState(); }
class SplashState extends State<Splash>{
  @override void initState(){ super.initState(); checkLogin(); }
  checkLogin() async {
    await Future.delayed(Duration(seconds:2));
    try{ final p=await SharedPreferences.getInstance(); final email=p.getString('registered_email_permanent'); final logged=p.getBool('is_logged_in')??false; if(email!=null&&logged){ if(mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder:(_)=>MainNav(email:email,isAdmin:p.getBool('is_admin')??false))); } else { if(mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder:(_)=>const LoginScreen())); } } catch(e){ if(mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder:(_)=>const LoginScreen())); }
  }
  @override Widget build(BuildContext c)=>const Scaffold(backgroundColor:Colors.black, body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center, children:[Icon(Icons.movie_filter,size:80,color:Colors.orange), SizedBox(height:10), Text('ONYX MOVIES',style:TextStyle(color:Colors.white,fontSize:22,fontWeight:FontWeight.bold)), SizedBox(height:20), CircularProgressIndicator(color:Colors.orange)])));
}
class LoginScreen extends StatefulWidget{ const LoginScreen({super.key}); @override State<LoginScreen> createState()=>LoginScreenState(); }
class LoginScreenState extends State<LoginScreen>{
  final emailC=TextEditingController(); final passC=TextEditingController(); String err='';
  void doLogin() async {
    if(emailC.text.trim().isEmpty||passC.text.isEmpty){ setState(()=>err='Enter email and password'); return; }
    final p=await SharedPreferences.getInstance(); final email=emailC.text.trim().toLowerCase(); bool isAdmin=email=='mugabibenjamin14@gmail.com'&&passC.text=='Mugabibe+-@1'; await p.setString('registered_email_permanent',email); await p.setBool('is_logged_in',true); await p.setBool('is_admin',isAdmin); if(mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder:(_)=>MainNav(email:email,isAdmin:isAdmin)));
  }
  @override Widget build(BuildContext c)=>Scaffold(backgroundColor:Colors.black, body:Center(child:SingleChildScrollView(padding:EdgeInsets.all(24), child:Column(mainAxisAlignment:MainAxisAlignment.center, children:[Icon(Icons.movie_filter,size:70,color:Colors.orange), SizedBox(height:10), Text('ONYX MOVIES',style:TextStyle(fontSize:24,fontWeight:FontWeight.bold,color:Colors.orange)), SizedBox(height:30), TextField(controller:emailC,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'Email',filled:true,fillColor:Colors.grey[900],border:OutlineInputBorder())), SizedBox(height:12), TextField(controller:passC,obscureText:true,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'Password',filled:true,fillColor:Colors.grey[900],border:OutlineInputBorder())), SizedBox(height:12), if(err.isNotEmpty) Text(err,style:TextStyle(color:Colors.red)), SizedBox(height:20), SizedBox(width:double.infinity,height:50, child:ElevatedButton(onPressed:doLogin,style:ElevatedButton.styleFrom(backgroundColor:Colors.orange), child:Text('LOGIN FOREVER',style:TextStyle(color:Colors.white))))]))));
}
class MainNav extends StatefulWidget{ final String email; final bool isAdmin; const MainNav({super.key,required this.email,required this.isAdmin}); @override State<MainNav> createState()=>MainNavState(); }
class MainNavState extends State<MainNav>{ int idx=0; @override Widget build(BuildContext c){ final pages=[HomeSafe(email:widget.email,isAdmin:widget.isAdmin), ProfileSafe(email:widget.email,isAdmin:widget.isAdmin)]; return Scaffold(backgroundColor:Colors.black, body:pages[idx], bottomNavigationBar:BottomNavigationBar(currentIndex:idx,backgroundColor:Colors.black,selectedItemColor:Colors.orange,unselectedItemColor:Colors.white54,onTap:(i)=>setState(()=>idx=i), items:[BottomNavigationBarItem(icon:Icon(Icons.home),label:'Home'), BottomNavigationBarItem(icon:Icon(Icons.person),label:'Profile')])); } }
class SafePoster extends StatelessWidget{
  final String base64Str; const SafePoster({super.key,required this.base64Str});
  @override Widget build(BuildContext c){
    if(base64Str.isEmpty||base64Str.length<20) return Icon(Icons.movie,color:Colors.white30,size:50);
    try{ final bytes=base64Decode(base64Str); return Image.memory(bytes,fit:BoxFit.cover,width:double.infinity,height:double.infinity,errorBuilder:(a,b,d)=>Icon(Icons.movie,color:Colors.white30)); } catch(e){ return Icon(Icons.movie,color:Colors.white30,size:50); }
  }
}
class HomeSafe extends StatefulWidget{ final String email; final bool isAdmin; const HomeSafe({super.key,required this.email,required this.isAdmin}); @override State<HomeSafe> createState()=>HomeSafeState(); }
class HomeSafeState extends State<HomeSafe>{
  final ref=FirebaseDatabase.instance.ref('movies'); String debugMsg='Loading...';
  @override Widget build(BuildContext c){
    return SafeArea(child:Column(children:[
      Container(color:Colors.black,padding:EdgeInsets.all(12), child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start, children:[Text('ONYX MOVIES - FIXED',style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold,fontSize:14)), Text(widget.email,style:TextStyle(color:Colors.green,fontSize:10)), Text(debugMsg,style:TextStyle(color:Colors.orange,fontSize:9))])), if(widget.isAdmin) ElevatedButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>AdminPanel(email:widget.email))),style:ElevatedButton.styleFrom(backgroundColor:Colors.orange), child:Text('ADMIN',style:TextStyle(fontSize:11)))])),
      Expanded(child:StreamBuilder(stream:ref.onValue, builder:(context,snapshot){
        if(snapshot.hasError){ return Center(child:Column(mainAxisAlignment:MainAxisAlignment.center, children:[Icon(Icons.error,color:Colors.red,size:50), Text('Firebase Error: ${snapshot.error}',style:TextStyle(color:Colors.white)), Text('FIX: Firebase > Realtime DB > Rules >.read true.write true',style:TextStyle(color:Colors.white54,fontSize:11))])); }
        if(!snapshot.hasData) return Center(child:CircularProgressIndicator(color:Colors.orange));
        final data=snapshot.data!.snapshot.value; if(data==null) return Center(child:Text('No movies yet.\nGo to ADMIN > Upload',style:TextStyle(color:Colors.white54),textAlign:TextAlign.center));
        try{ final map=Map<String,dynamic>.from(data as Map); final list=map.entries.toList(); WidgetsBinding.instance.addPostFrameCallback((_){ if(mounted) setState(()=>debugMsg='Loaded ${list.length} movies'); }); return GridView.builder(padding:EdgeInsets.all(8), gridDelegate:SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:2,childAspectRatio:0.7,crossAxisSpacing:8,mainAxisSpacing:8), itemCount:list.length, itemBuilder:(c,i){ try{ final m=Map<String,dynamic>.from(list[i].value as Map); final title=m['title']?.toString()??'No Title'; final poster=m['posterBase64']?.toString()??''; return Card(color:Color(0xFF1E1E1E), child:Column(children:[Expanded(child:ClipRRect(borderRadius:BorderRadius.vertical(top:Radius.circular(4)), child:SafePoster(base64Str:poster))), Padding(padding:EdgeInsets.all(6), child:Text(title,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:Colors.white,fontSize:11)))])); } catch(e){ return Card(color:Color(0xFF1E1E1E), child:Center(child:Icon(Icons.error,color:Colors.red))); } }); } catch(e){ return Center(child:Text('Data error: $e',style:TextStyle(color:Colors.white))); }
      }))
    ]));
  }
}
class ProfileSafe extends StatelessWidget{ final String email; final bool isAdmin; const ProfileSafe({super.key,required this.email,required this.isAdmin}); @override Widget build(BuildContext c)=>SafeArea(child:ListView(padding:EdgeInsets.all(16), children:[Icon(Icons.person,size:60,color:Colors.orange), SizedBox(height:10), Text(email,textAlign:TextAlign.center,style:TextStyle(color:Colors.white,fontWeight:FontWeight.bold)), SizedBox(height:5), Text('Auto-login saved forever',textAlign:TextAlign.center,style:TextStyle(color:Colors.green,fontSize:12)), SizedBox(height:20), if(isAdmin) ElevatedButton(onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>AdminPanel(email:email))),style:ElevatedButton.styleFrom(backgroundColor:Colors.orange), child:Text('OPEN ADMIN PANEL')), SizedBox(height:10), ElevatedButton(onPressed:() async {final p=await SharedPreferences.getInstance(); await p.clear(); if(c.mounted) Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const LoginScreen()));},style:ElevatedButton.styleFrom(backgroundColor:Colors.red), child:Text('LOGOUT'))])); }
class AdminPanel extends StatefulWidget{ final String email; const AdminPanel({super.key,required this.email}); @override State<AdminPanel> createState()=>AdminPanelState(); }
class AdminPanelState extends State<AdminPanel>{ int idx=0; @override Widget build(BuildContext c){ final pages=[AdminHome(email:widget.email), AdminUpload(), AdminList()]; return Scaffold(backgroundColor:Colors.black, appBar:AppBar(backgroundColor:Colors.black, title:Text('ADMIN: ${widget.email}',style:TextStyle(fontSize:12,color:Colors.orange))), body:pages[idx], bottomNavigationBar:BottomNavigationBar(currentIndex:idx,backgroundColor:Colors.black,selectedItemColor:Colors.orange,unselectedItemColor:Colors.white54,onTap:(i)=>setState(()=>idx=i), items:[BottomNavigationBarItem(icon:Icon(Icons.dashboard),label:'Dash'), BottomNavigationBarItem(icon:Icon(Icons.upload),label:'Upload'), BottomNavigationBarItem(icon:Icon(Icons.list),label:'Manage')])); } }
class AdminHome extends StatelessWidget{ final String email; AdminHome({super.key,required this.email}); final ref=FirebaseDatabase.instance.ref('movies'); @override Widget build(BuildContext c)=>StreamBuilder(stream:ref.onValue, builder:(c,snap){int total=0; if(snap.hasData&&snap.data!.snapshot.value!=null) total=Map<String,dynamic>.from(snap.data!.snapshot.value as Map).length; return Center(child:Column(mainAxisAlignment:MainAxisAlignment.center, children:[Text('Welcome $email',style:TextStyle(color:Colors.white)), SizedBox(height:10), Text('Total Movies: $total',style:TextStyle(color:Colors.green,fontSize:20))]));}); }
class AdminList extends StatelessWidget{ const AdminList({super.key}); @override Widget build(BuildContext c){ final ref=FirebaseDatabase.instance.ref('movies'); return StreamBuilder(stream:ref.onValue, builder:(c,snap){ if(!snap.hasData) return Center(child:CircularProgressIndicator()); if(snap.data!.snapshot.value==null) return Center(child:Text('No movies',style:TextStyle(color:Colors.white54))); final map=Map<String,dynamic>.from(snap.data!.snapshot.value as Map); final list=map.entries.toList(); return ListView.builder(itemCount:list.length, itemBuilder:(c,i){ final m=Map<String,dynamic>.from(list[i].value as Map); return Card(color:Color(0xFF1E1E1E), child:ListTile(title:Text(m['title']??'',style:TextStyle(color:Colors.white)), trailing:IconButton(icon:Icon(Icons.delete,color:Colors.red), onPressed:() async {await ref.child(list[i].key).remove();}))); }); }); } }
class AdminUpload extends StatefulWidget{ const AdminUpload({super.key}); @override State<AdminUpload> createState()=>AdminUploadState(); }
class AdminUploadState extends State<AdminUpload>{
  final titleC=TextEditingController(); final descC=TextEditingController(); Uint8List? poster; final picker=ImagePicker(); bool up=false;
  pick() async {final x=await picker.pickImage(source:ImageSource.gallery,imageQuality:30); if(x!=null){final b=await x.readAsBytes(); setState(()=>poster=b);} }
  upload() async { if(titleC.text.isEmpty||poster==null){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Need Title + Poster'))); return; } setState(()=>up=true); try{ final ref=FirebaseDatabase.instance.ref('movies').push(); await ref.set({'title':titleC.text,'description':descC.text,'posterBase64':base64Encode(poster!),'timestamp':ServerValue.timestamp}); if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Uploaded OK'),backgroundColor:Colors.green)); titleC.clear(); descC.clear(); setState(()=>poster=null); } catch(e){ if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Error: $e'))); } setState(()=>up=false); }
  @override Widget build(BuildContext c)=>ListView(padding:EdgeInsets.all(16), children:[TextField(controller:titleC,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'Title *',border:OutlineInputBorder())), SizedBox(height:10), TextField(controller:descC,style:TextStyle(color:Colors.white),decoration:InputDecoration(labelText:'Description',border:OutlineInputBorder())), SizedBox(height:10), ElevatedButton(onPressed:pick, child:Text(poster==null?'Pick Poster *':'Poster OK: ${poster!.length} bytes')), if(poster!=null) Container(height:100,margin:EdgeInsets.only(top:10), child:Image.memory(poster!,fit:BoxFit.cover)), SizedBox(height:20), SizedBox(height:50, child:ElevatedButton(onPressed:up?null:upload,style:ElevatedButton.styleFrom(backgroundColor:Colors.orange), child:Text(up?'Uploading...':'UPLOAD MOVIE')))]);
}
